# Lunar Konstruksi - CMS Seed All Pages
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Write-Seed([string]$Message) { Write-Host "[CMS SEED] $Message" -ForegroundColor Cyan }
function Fail-Seed([string]$Message) { Write-Host ""; Write-Host "[CMS SEED] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Write-Utf8NoBom([string]$Path, [string]$Content) { $parent = Split-Path -Parent $Path; if ($parent -and -not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }; $encoding = New-Object System.Text.UTF8Encoding($false); [System.IO.File]::WriteAllText($Path, $Content, $encoding) }
function Decode([string]$Value) { return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($Value)) }

$repoRoot = (& git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) { Fail-Seed "Jalankan dari root repository Lunar Konstruksi." }
$repoRoot = $repoRoot.Trim()
Set-Location $repoRoot
$trackedStatus = & git status --porcelain --untracked-files=no
if ($trackedStatus) { Write-Host $trackedStatus; Fail-Seed "Ada perubahan TRACKED. Commit/stash dulu agar installer aman." }
$required = @(
  "package.json",
  "features/pages/server.ts",
  "features/navigation/server.ts",
  "features/site-settings/server.ts",
  "components/admin/cms/cms-api.ts",
  "components/admin/cms/cms-ui.tsx",
  "components/admin/cms/cms-workspace-nav.tsx",
  "app/api/admin/cms/revalidate/route.ts"
)
$missing = @($required | Where-Object { -not (Test-Path -LiteralPath $_) })
if ($missing.Count -gt 0) { $missing | ForEach-Object { Write-Host "  - $_" }; Fail-Seed "Fondasi CMS belum lengkap. Pastikan Fase 1-7 sudah terpasang." }

Write-Seed "Menambahkan CMS seed manager..."
$payload = @{}
$payload["CMS_SEED_GUIDE.md"] = ""
$payload["app/admin/(dashboard)/cms/seed/page.tsx"] = "aW1wb3J0IHsgQ21zU2VlZE1hbmFnZXIgfSBmcm9tICJAL2NvbXBvbmVudHMvYWRtaW4vY21zL2Ntcy1zZWVkLW1hbmFnZXIiOwoKZXhwb3J0IGRlZmF1bHQgZnVuY3Rpb24gQ21zU2VlZFBhZ2UoKSB7CiAgcmV0dXJuIDxDbXNTZWVkTWFuYWdlciAvPjsKfQo="
$payload["app/api/admin/cms/seed/route.ts"] = ""
$payload["components/admin/cms/cms-seed-manager.tsx"] = ""
$payload["components/admin/cms/cms-workspace-nav.tsx"] = ""
$payload["features/cms-seed/cms-seed.data.ts"] = ""
$payload["features/cms-seed/cms-seed.service.ts"] = ""
$payload["features/cms-seed/server.ts"] = "ZXhwb3J0ICogZnJvbSAiLi9jbXMtc2VlZC5kYXRhIjsKZXhwb3J0ICogZnJvbSAiLi9jbXMtc2VlZC5zZXJ2aWNlIjsK"

foreach ($entry in $payload.GetEnumerator()) { $target = Join-Path $repoRoot $entry.Key; Write-Utf8NoBom $target (Decode $entry.Value); Write-Host "[CMS SEED] write  $($entry.Key)" -ForegroundColor DarkGray }
Write-Host ""
Write-Host "[CMS SEED] Installer selesai." -ForegroundColor Green
Write-Host "Buka: http://localhost:3000/admin/cms/seed" -ForegroundColor Green
Write-Host "Login admin, lalu klik: Seed semua halaman" -ForegroundColor Green
Write-Host ""
Write-Host "Validasi:" -ForegroundColor Cyan
Write-Host "  npm run typecheck"
Write-Host "  npm run build"
